   377→    def login(self):
   378→        username = self.user_input.text().strip()
   379→        password = self.pwd_input.text()
   380→
   381→        if not username or not password:
   382→            self.show_message('提示', '请输入用户名和密码！', QMessageBox.Warning)
   383→            return
   384→
   385→        result = self.db_manager.fetch_one(
   386→            'SELECT role FROM users WHERE username=? AND password=?',
   387→            (username, password)
   388→        )
   389→
   390→        if result:
   391→            self.user_role = result[0]
   392→            self.username = username
   393→            self.accept()
   394→        else:
   395→            self.show_message('错误', '用户名或密码错误！', QMessageBox.Critical)
