        self.processing_date.setDate(QDate.currentDate())
        self.knitting_qty = QLineEdit()
        self.knitting_wage = QLineEdit()

        workshop_layout.addWidget(QLabel('加工车间:'), 0, 0)
        workshop_layout.addWidget(self.workshop_name, 0, 1)
