        sewing_layout.addWidget(QLabel('手缝数量:'), 0, 2)
        sewing_layout.addWidget(self.sewing_qty, 0, 3)
        sewing_layout.addWidget(QLabel('手缝工资:'), 1, 0)
        sewing_layout.addWidget(self.sewing_wage, 1, 1)

