            float(self.sewing_wage.text()) if self.sewing_wage.text() else 0.0,
            self.username,
            current_time
        )

        if self.db_manager.execute_query(query, params):
            QMessageBox.information(self, '成功', '工资记录保存成功！')
            self.accept()
        else:
