# -*- coding: utf-8 -*-
"""
向阳厂数据管理系统
权限等级：
1. 一线工厂 - 数据录入权限
2. 财务 - 数据核查与修改权限
"""

import sys
import sqlite3
from datetime import datetime
import os
from data import DatabaseManager, get_database_path
from goodsprocess import GoodsProcessingTab, GoodsProcessingDialog
from wage import WageCalculationDialog, WageCalculationTab
from PyQt5.QtWidgets import (
    QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout,
    QLabel, QLineEdit, QPushButton, QTableWidget, QTableWidgetItem,
    QMessageBox, QDialog, QTabWidget, QComboBox, QDateEdit, QHeaderView,
    QTextEdit, QGridLayout, QGroupBox, QSplitter, QFileDialog, QFrame, 
    QCheckBox, QStatusBar, QGraphicsDropShadowEffect
)
from PyQt5.QtCore import Qt, QDate, QTimer, QDateTime
from PyQt5.QtGui import QFont, QColor, QIcon, QPalette

class LoginDialog(QDialog):
    """登录对话框 - 简洁版"""

    def __init__(self, db_manager):
        super().__init__()
        self.db_manager = db_manager
        self.user_role = None
        self.username = None
        self.setWindowFlags(Qt.FramelessWindowHint)
        self.setAttribute(Qt.WA_TranslucentBackground)
        self.init_ui()

    def mousePressEvent(self, event):
        """实现窗口拖动"""
        if event.button() == Qt.LeftButton:
            self.drag_position = event.globalPos() - self.frameGeometry().topLeft()
            event.accept()

    def mouseMoveEvent(self, event):
        """实现窗口拖动"""
        if event.buttons() == Qt.LeftButton:
            self.move(event.globalPos() - self.drag_position)
            event.accept()

    def init_ui(self):
        self.setFixedSize(400, 520)

        # 主布局
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(0, 0, 0, 0)

        # 创建主容器
        container = QWidget()
        container.setObjectName("container")
        container.setStyleSheet("""
            QWidget#container {
                background-color: white;
                border-radius: 12px;
            }
        """)

        # 添加阴影效果
        shadow = QGraphicsDropShadowEffect()
        shadow.setBlurRadius(25)
        shadow.setColor(QColor(0, 0, 0, 60))
        shadow.setOffset(0, 3)
        container.setGraphicsEffect(shadow)

        container_layout = QVBoxLayout()
        container_layout.setContentsMargins(35, 35, 35, 35)
        container_layout.setSpacing(20)

        # ========== 顶部标题区域 ==========
        title_layout = QVBoxLayout()
        title_layout.setSpacing(8)

        # 图标
        icon_label = QLabel('🏭')
        icon_label.setFont(QFont('Segoe UI Emoji', 40))
        icon_label.setAlignment(Qt.AlignCenter)
        icon_label.setStyleSheet("color: #2196F3; background: transparent;")
        title_layout.addWidget(icon_label)

        # 主标题
        title = QLabel('向阳厂管理系统')
        title.setFont(QFont('Microsoft YaHei', 20, QFont.Bold))
        title.setAlignment(Qt.AlignCenter)
        title.setStyleSheet("color: #212121; background: transparent;")
        title_layout.addWidget(title)

        # 副标题
        subtitle = QLabel('Factory Management System')
        subtitle.setFont(QFont('Arial', 11))
        subtitle.setAlignment(Qt.AlignCenter)
        subtitle.setStyleSheet("color: #757575; background: transparent;")
        title_layout.addWidget(subtitle)

        container_layout.addLayout(title_layout)
        container_layout.addSpacing(10)

        # ========== 登录表单区域 ==========
        form_layout = QVBoxLayout()
        form_layout.setSpacing(18)

        # 用户名
        user_label = QLabel('用户名')
        user_label.setFont(QFont('Microsoft YaHei', 11))
        user_label.setStyleSheet("color: #424242;")
        form_layout.addWidget(user_label)

        self.user_input = QLineEdit()
        self.user_input.setPlaceholderText('请输入用户名')
        self.user_input.setFixedHeight(42)
        self.user_input.setFont(QFont('Microsoft YaHei', 11))
        self.user_input.setStyleSheet("""
            QLineEdit {
                background-color: #F5F5F5;
                border: 2px solid #E0E0E0;
                border-radius: 6px;
                padding: 0 12px;
                color: #212121;
            }
            QLineEdit:focus {
                border: 2px solid #2196F3;
                background-color: white;
            }
            QLineEdit::placeholder {
                color: #9E9E9E;
            }
        """)
        form_layout.addWidget(self.user_input)

        # 密码
        pwd_label = QLabel('密码')
        pwd_label.setFont(QFont('Microsoft YaHei', 11))
        pwd_label.setStyleSheet("color: #424242;")
        form_layout.addWidget(pwd_label)

        self.pwd_input = QLineEdit()
        self.pwd_input.setPlaceholderText('请输入密码')
        self.pwd_input.setEchoMode(QLineEdit.Password)
        self.pwd_input.setFixedHeight(42)
        self.pwd_input.setFont(QFont('Microsoft YaHei', 11))
        self.pwd_input.setStyleSheet("""
            QLineEdit {
                background-color: #F5F5F5;
                border: 2px solid #E0E0E0;
                border-radius: 6px;
                padding: 0 12px;
                color: #212121;
            }
            QLineEdit:focus {
                border: 2px solid #2196F3;
                background-color: white;
            }
            QLineEdit::placeholder {
                color: #9E9E9E;
            }
        """)
        form_layout.addWidget(self.pwd_input)

        container_layout.addLayout(form_layout)
        container_layout.addSpacing(10)

        # ========== 按钮区域 ==========
        btn_layout = QVBoxLayout()
        btn_layout.setSpacing(10)

        # 登录按钮
        login_btn = QPushButton('登 录')
        login_btn.setFixedHeight(44)
        login_btn.setCursor(Qt.PointingHandCursor)
        login_btn.setFont(QFont('Microsoft YaHei', 12, QFont.Bold))
        login_btn.setStyleSheet("""
            QPushButton {
                background-color: #2196F3;
                color: white;
                border: none;
                border-radius: 6px;
            }
            QPushButton:hover {
                background-color: #1976D2;
            }
            QPushButton:pressed {
                background-color: #0D47A1;
            }
        """)
        login_btn.clicked.connect(self.login)
        btn_layout.addWidget(login_btn)

        # 取消按钮
        cancel_btn = QPushButton('取 消')
        cancel_btn.setFixedHeight(44)
        cancel_btn.setCursor(Qt.PointingHandCursor)
        cancel_btn.setFont(QFont('Microsoft YaHei', 12))
        cancel_btn.setStyleSheet("""
            QPushButton {
                background-color: #F5F5F5;
                color: #616161;
                border: 1px solid #E0E0E0;
                border-radius: 6px;
            }
            QPushButton:hover {
                background-color: #EEEEEE;
            }
            QPushButton:pressed {
                background-color: #E0E0E0;
            }
        """)
        cancel_btn.clicked.connect(self.reject)
        btn_layout.addWidget(cancel_btn)

        container_layout.addLayout(btn_layout)

        # ========== 底部提示 ==========
        tip_label = QLabel('默认账号: admin/admin123 或 factory/factory123')
        tip_label.setFont(QFont('Microsoft YaHei', 9))
        tip_label.setAlignment(Qt.AlignCenter)
        tip_label.setStyleSheet("color: #9E9E9E; background: transparent;")
        container_layout.addWidget(tip_label)

        container.setLayout(container_layout)
        main_layout.addWidget(container)
        self.setLayout(main_layout)

        # 设置默认焦点
        self.user_input.setFocus()

        # 连接回车键
        self.user_input.returnPressed.connect(self.pwd_input.setFocus)
        self.pwd_input.returnPressed.connect(self.login)

    def login(self):
        username = self.user_input.text().strip()
        password = self.pwd_input.text()

        if not username or not password:
            self.show_message('提示', '请输入用户名和密码！', QMessageBox.Warning)
            return

        result = self.db_manager.fetch_one(
            'SELECT role FROM users WHERE username=? AND password=?',
            (username, password)
        )

        if result:
            self.user_role = result[0]
            self.username = username
            self.accept()
        else:
            self.show_message('错误', '用户名或密码错误！', QMessageBox.Critical)

    def show_message(self, title, text, icon):
        """自定义消息框"""
        msg = QMessageBox(self)
        msg.setWindowTitle(title)
        msg.setText(text)
        msg.setIcon(icon)
        msg.setStyleSheet("""
            QMessageBox {
                background-color: white;
            }
            QLabel {
                color: #212121;
                font-size: 13px;
                min-width: 230px;
                padding: 8px;
            }
            QPushButton {
                background-color: #2196F3;
                color: white;
                border: none;
                padding: 6px 20px;
                border-radius: 4px;
                font-size: 12px;
                font-weight: bold;
                min-width: 70px;
            }
            QPushButton:hover {
                background-color: #1976D2;
            }
        """)
        msg.exec_()

class MainWindow(QMainWindow):
    """主窗口 - 优化版"""

    def __init__(self, user_role, username):
        super().__init__()
        self.user_role = user_role
        self.username = username
        self.db_manager = DatabaseManager()

        self.init_ui()
        self.showMaximized()

    def init_ui(self):
        # 窗口设置
        self.setWindowTitle(f'向阳厂数据管理系统 - {self.username} ({self.user_role})')

        # 设置全局样式 - 简洁自然
        self.setStyleSheet("""
            QMainWindow {
                background-color: #FAFAFA;
            }
            QTabWidget::pane {
                border: 1px solid #E0E0E0;
                background-color: white;
                border-radius: 0px;
                top: -1px;
            }
            QTabBar::tab {
                background-color: #F5F5F5;
                color: #616161;
                padding: 14px 30px;
                margin-right: 2px;
                font-size: 13px;
                font-weight: bold;
                border: 1px solid #E0E0E0;
                border-bottom: none;
            }
            QTabBar::tab:selected {
                background-color: white;
                color: #2196F3;
                border-bottom: 2px solid #2196F3;
            }
            QTabBar::tab:hover:!selected {
                background-color: #EEEEEE;
            }
            QStatusBar {
                background-color: white;
                color: #616161;
                border-top: 1px solid #E0E0E0;
                font-size: 12px;
            }
        """)

        # 中央部件
        central_widget = QWidget()
        main_layout = QVBoxLayout()
        main_layout.setContentsMargins(15, 15, 15, 15)
        main_layout.setSpacing(15)

        # ========== 顶部工具栏 ==========
        toolbar = QWidget()
        toolbar.setFixedHeight(60)
        toolbar.setStyleSheet("""
            QWidget {
                background-color: white;
                border-bottom: 1px solid #E0E0E0;
            }
        """)

        toolbar_layout = QHBoxLayout()
        toolbar_layout.setContentsMargins(25, 0, 25, 0)

        # 左侧信息
