        send_layout.addWidget(QLabel('客户名称:'), 0, 0)
        send_layout.addWidget(self.customer_name, 0, 1)
        send_layout.addWidget(QLabel('客户款号:'), 0, 2)
        send_layout.addWidget(self.customer_style_no, 0, 3)
