        self.diff_receive_display = QLineEdit()
        self.diff_receive_display.setReadOnly(True)
        self.diff_receive_display.setStyleSheet("color: red; font-weight: bold;")

        receive_layout.addWidget(QLabel('收货数量:'), 0, 0)
