        # 连接信号槽（实时计算差异）
        self.customer_send_qty.textChanged.connect(self._calculate_diffs)
        self.factory_receive_qty.textChanged.connect(self._calculate_diffs)
        self.factory_send_qty.textChanged.connect(self._calculate_diffs)
