def show_styled_message(parent, title, text, icon=QMessageBox.Information):
    """显示统一样式的消息框"""
    msg = QMessageBox(parent)
    msg.setWindowTitle(title)
    msg.setText(text)
    msg.setIcon(icon)
    msg.setStyleSheet("""
        QMessageBox {
            background-color: white;
        }
        QLabel {
            color: #212121;
            font-size: 13px;
            min-width: 240px;
            padding: 10px;
        }
        QPushButton {
            background-color: #2196F3;
