            QFrame {
                background-color: white;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
            }
        """)

        search_layout = QHBoxLayout()
        search_layout.setContentsMargins(15, 12, 15, 12)
        search_layout.setSpacing(12)

        # 类型筛选
