        self.type_filter.currentTextChanged.connect(self.load_data)
        self.type_filter.setFont(QFont('Microsoft YaHei', 11))
        self.type_filter.setStyleSheet("""
            QComboBox {
                background-color: #F5F5F5;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
                padding: 6px 12px;
                min-width: 100px;
