            QComboBox:hover {
                border: 1px solid #2196F3;
            }
            QComboBox::drop-down {
                border: none;
                width: 20px;
            }
        """)

        # 搜索关键词
        keyword_label = QLabel('关键词')
        keyword_label.setFont(QFont('Microsoft YaHei', 11))
        keyword_label.setStyleSheet("color: #424242; margin-left: 15px;")

        self.search_input = QLineEdit()
        self.search_input.setPlaceholderText('搜索客户名称/款号...')
        self.search_input.returnPressed.connect(self.search_data)
        self.search_input.setFont(QFont('Microsoft YaHei', 11))
        self.search_input.setStyleSheet("""
            QLineEdit {
                background-color: #F5F5F5;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
                padding: 6px 12px;
                min-width: 200px;
