        search_btn = QPushButton('搜索')
        search_btn.clicked.connect(self.search_data)
        search_btn.setCursor(Qt.PointingHandCursor)
        search_btn.setFont(QFont('Microsoft YaHei', 11))
        search_btn.setFixedHeight(36)
        search_btn.setStyleSheet("""
            QPushButton {
                background-color: #2196F3;
                color: white;
                border: none;
                border-radius: 4px;
                padding: 0 24px;
            }
            QPushButton:hover {
                background-color: #1976D2;
            }
        """)

        refresh_btn = QPushButton('刷新')
        refresh_btn.clicked.connect(self.load_data)
        refresh_btn.setCursor(Qt.PointingHandCursor)
        refresh_btn.setFont(QFont('Microsoft YaHei', 11))
        refresh_btn.setFixedHeight(36)
        refresh_btn.setStyleSheet("""
            QPushButton {
                background-color: #F5F5F5;
                color: #616161;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
                padding: 0 24px;
            }
            QPushButton:hover {
                background-color: #EEEEEE;
            }
        """)

        search_layout.addWidget(type_label)
        search_layout.addWidget(self.type_filter)
        search_layout.addWidget(keyword_label)
        search_layout.addWidget(self.search_input)
        search_layout.addWidget(search_btn)
        search_layout.addWidget(refresh_btn)
        search_layout.addStretch()

        search_card.setLayout(search_layout)
        layout.addWidget(search_card)

        # ===== 操作按钮区域 =====
        button_card = QFrame()
        button_card.setStyleSheet("""
            QFrame {
                background-color: white;
                border: 1px solid #E0E0E0;
                border-radius: 4px;
            }
        """)

        button_layout = QHBoxLayout()
        button_layout.setContentsMargins(15, 12, 15, 12)
        button_layout.setSpacing(10)

        # 新增按钮
        add_btn = QPushButton('新增记录')
        add_btn.clicked.connect(self.add_record)
        add_btn.setCursor(Qt.PointingHandCursor)
        add_btn.setFont(QFont('Microsoft YaHei', 11))
        add_btn.setFixedHeight(36)
        add_btn.setStyleSheet("""
            QPushButton {
                background-color: #4CAF50;
                color: white;
                border: none;
                border-radius: 4px;
                padding: 0 24px;
            }
            QPushButton:hover {
                background-color: #45A049;
            }
            QPushButton:disabled {
                background-color: #BDBDBD;
            }
        """)

        # 修改按钮
        edit_btn = QPushButton('修改记录')
        edit_btn.clicked.connect(self.edit_record)
        edit_btn.setCursor(Qt.PointingHandCursor)
        edit_btn.setFont(QFont('Microsoft YaHei', 11))
        edit_btn.setFixedHeight(36)
        edit_btn.setStyleSheet("""
            QPushButton {
                background-color: #FF9800;
                color: white;
                border: none;
                border-radius: 4px;
                padding: 0 24px;
            }
            QPushButton:hover {
