                background: #1e8449;
            }
        """)
        save_btn.clicked.connect(self.save)

        cancel_btn = QPushButton('❌ 取消')
        cancel_btn.setFixedHeight(40)
        cancel_btn.setCursor(Qt.PointingHandCursor)
        cancel_btn.setStyleSheet("""
            QPushButton {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
