            QPushButton {
                background-color: #2196F3;
                color: white;
                border: none;
                padding: 8px 24px;
                border-radius: 4px;
                font-size: 16px;
                font-weight: bold;
                min-width: 70px;
            }
            QPushButton:hover {
                background-color: #1976D2;
            }
        """)
        msg.exec_()

    def logout(self):
        """退出登录"""
        msg = QMessageBox(self)
        msg.setWindowTitle('确认退出')
        msg.setText('确定要退出登录吗？')
        msg.setIcon(QMessageBox.Question)
        msg.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
        msg.setDefaultButton(QMessageBox.No)
        msg.setStyleSheet("""
            QMessageBox {
                background-color: white;
            }
            QLabel {
                color: #212121;
                font-size: 16px;
                min-width: 240px;
                padding: 10px;
            }
            QPushButton {
                background-color: #2196F3;
                color: white;
                border: none;
                padding: 8px 24px;
                border-radius: 4px;
                font-size: 16px;
                font-weight: bold;
                min-width: 70px;
            }
            QPushButton:hover {
                background-color: #1976D2;
            }
        """)

        if msg.exec_() == QMessageBox.Yes:
            self.db_manager.close()
            self.close()

    def closeEvent(self, event):
        """关闭事件"""
        self.db_manager.close()
        event.accept()

def main():
    app = QApplication(sys.argv)

    # 设置应用样式
    app.setStyle('Fusion')

    # 设置全局字体 - 增大字体
    font = QFont('Microsoft YaHei', 13)
    app.setFont(font)

    # 创建数据库管理器（使用正确的数据库路径）
    db_path = get_database_path()
    db_manager = DatabaseManager(db_path)

    # 显示登录对话框
    login_dialog = LoginDialog(db_manager)

    if login_dialog.exec_() == QDialog.Accepted:
        # 创建主窗口
        main_window = MainWindow(login_dialog.user_role, login_dialog.username)
        main_window.show()

        sys.exit(app.exec_())
    else:
        sys.exit(0)


if __name__ == '__main__':
    main()

