                factory_send_date, factory_send_method, factory_send_qty,
                customer_receive_qty, created_by
            FROM goods_processing_v2 WHERE id=?
        '''
        result = self.db_manager.fetch_one(query, (self.record_id,))

        if result:
            # 设置货物类型（如果是织纱，标题显示织纱）
