                self.factory_send_date.date().toString('yyyy-MM-dd'),
                self.factory_send_method.currentText(),
                factory_send_qty,
                customer_receive_qty,
                diff_factory_customer,
                self.username,
                current_time,
                self.record_id
            )

        if self.db_manager.execute_query(query, params):
            show_styled_message(self, '成功', '数据保存成功！', QMessageBox.Information)
            self.accept()
        else:
            show_styled_message(self, '错误', '数据保存失败！', QMessageBox.Critical)
